"""One-shot exact publication check. No commit/push or numerical execution."""
from pathlib import Path
import hashlib,json,subprocess
R=Path(__file__).resolve().parents[4];D=Path(__file__).resolve().parent
NAMES = ['diagnostics/simplex-core-architecture/DIRECT-LU-CORRECTNESS.md', 'diagnostics/simplex-core-architecture/STATUS.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-admission.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-audit.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-invocation.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-launch-pins.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-launcher.log', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-posthost.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-prehost.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-reservation.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-run/current.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-run/group-1.toml', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-run/pins.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-run/process.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-run/raw.toml', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-run/resources.jsonl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-run/run.log', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-run/started-1.toml', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-seal-host.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/green-sealed-pins.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-admission.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-audit.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-invocation.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-launch-pins.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-launcher.log', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-posthost.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-prehost.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-reservation.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-run/current.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-run/group-1.toml', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-run/pins.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-run/process.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-run/raw.toml', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-run/resources.jsonl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-run/run.log', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-run/started-1.toml', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-seal-host.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/red-sealed-pins.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/stage-green-review.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/stage-red-review.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/STATUS.md.before-correctness', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/closure.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/closure.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/continuation.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/final-host.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/final-host.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/postcheck.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/postcheck.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/publication.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/publication.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/review.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/review.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/roadmap.md.before-correctness', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/source-analysis.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-CORRECTNESS/source-analysis.py', 'docs/superpowers/plans/2026-10-11-simplex-core-architecture.md']
def git(*args):return subprocess.check_output(['git',*args],cwd=R,text=True).strip()
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
closure=json.loads((D/'closure.json').read_text())
if not closure['all_passed'] or not all(sha(R/n)==h for n,h in closure['sha256'].items()):raise SystemExit('Closure failed or bindings changed')
if git('diff','--cached','--name-only'):raise SystemExit('Index must start empty')
selfname=str((D/'publication.json').relative_to(R));other=[n for n in NAMES if n!=selfname]
if any(not (R/n).is_file() for n in other):raise SystemExit('Missing declared file')
subprocess.run(['git','add','--',*other],cwd=R,check=True)
if sorted(git('diff','--cached','--name-only').splitlines())!=sorted(other):raise SystemExit('Initial exact staged set mismatch')
blobs={n:git('rev-parse',':'+n) for n in other}
if any(git('hash-object',n)!=h for n,h in blobs.items()):raise SystemExit('Staged/working mismatch')
subprocess.run(['git','diff','--cached','--check'],cwd=R,check=True)
with (D/'publication.json').open('x') as f:json.dump({'all_passed':True,'scope':'RED accepted, GREEN failed and preserved; diagnostic publication only, no correctness/performance acceptance or promotion','exact_names':NAMES,'staged_blobs_excluding_self':blobs,'sha256':{n:sha(R/n) for n in other},'self_binding':'Included in exact staged set, bound by committed tree; postcommit verifies actual self blob too.'},f,indent=2);f.write('\n')
subprocess.run(['git','add','--',selfname],cwd=R,check=True)
if sorted(git('diff','--cached','--name-only').splitlines())!=NAMES:raise SystemExit('Final exact staged set mismatch')
subprocess.run(['git','diff','--cached','--check'],cwd=R,check=True)
print(json.dumps({'all_passed':True,'exact_staged_names':len(NAMES),'bound_other_blobs':len(blobs)}))
